        :return: If the sender or the receiver is not in the Chat, returns False, otherwise, returns True.
        """
        if sender not in self.users:
            return False
        if receiver not in self.users:
            return False
        self.users[sender].append(message)
        self.users[receiver].append(message)
        return True


    def get_messages(self, username):
        messages = []
        for sender, users in self.users.items():
            for user in users:
                if user[1] == username:
                    messages.append({'sender': sender, 'receiver': user[0], 'message': user[1], 'timestamp': datetime.now()})
