        :param data:list, data list
        :return:float, the mean value
        >>> ds = DataStatistics()
        >>> ds.mean([1, 2, 3, 4, 5])
        3.00
        """
        if isinstance(data, Counter):
            return data.most_common(1)[0][0]
        else:
            return sum(data) / len(data)

