    """
    MahjongConnect is a class representing a game board for Mahjong Connect with features like creating the board, checking valid moves, finding paths, removing icons, and checking if the game is over.
    """

    def __init__(self, BOARD_SIZE, ICONS):
        """
        initialize the board size and the icon list, create the game board
        :param BOARD_SIZE: list of two integer numbers, representing the number of rows and columns of the game board
        :param ICONS: list of string, representing the icons
        >>>mc = MahjongConnect([4, 4], ['a', 'b', 'c'])
        mc.BOARD_SIZE = [4, 4]
        mc.ICONS = ['a', 'b', 'c']
        mc.board = mc.create_board()
        """
        self.BOARD_SIZE = BOARD_SIZE
        self.ICONS = ICONS
        self.board = self.create_board()



    def create_board(self):
        board = []
        for i in range(self.BOARD_SIZE[0]):
            row = []
            for j in range(self.BOARD_SIZE[1]):
                row.append(self.ICONS[random.randint(0, len(self.ICONS) - 1)])
            board.append(row)
        return board

    def print_board(self):
        board = self.create_board()
        for row in board:
            print("".join(row))

    def is_valid_move(pos1, pos2):
        row1, col1 = pos1
        row2, col2 = pos2

        # check if the move is within the game board range
        if row1 < 0 or row1 >= self.BOARD_SIZE[0] or row2 < 0 or row2 >= self.BOARD_SIZE[1] or col1 < 0 or col1 >= self.BOARD_SIZE[1] or col2 < 0 or col2 >= self.BOARD_SIZE[1]:
            return False

        # check if the two positions are not the same
        if row1 == row2 or col1 == col2:
            return False

        # check if the two positions have the same icon
        if row1[col1] != row2[col2]:
            return False

        # check if there is a valid path between the two positions
        for i in range(len(self.board)):
            for j in range(len(self.board[i])):
                if self.board[i][j] == self.board[row1[0]][col1[0]]:
                    if self.is_valid_move(pos1, (i, j)) or self.is_valid_move(pos2, (i, j)) or self.is_valid_move(pos2, (row1[0], j)) or self.is_valid_move(pos2, (row1[0], col1[0])):
                        return False
        return True



    def remove_icons(self, pos1, pos2):
        row1, col1 = pos1
        row2, col2 = pos2

        # check if the move is within the game board range
        if row1 < 0 or row1 >= self.BOARD_SIZE[0] or row2 < 0 or row2 >= self.BOARD_SIZE[1] or col1 < 0 or col1 >= self.BOARD_SIZE[1] or col2 < 0 or col2 >= self.BOARD_SIZE[1]:
            return False

        # check if the two positions are not the same
        if row1 == row2 or col1 == col2:
            return False

        # check if the two positions have the same icon
        if row1[col1] != row2[col2]:
            return False

        # check if there is a valid path between the two positions
        for i in range(len(self.board)):
            for j in range(len(self.board[i])):
